return ['domain'=>'exchange-rate-pricing-for-woocommerce','plural-forms'=>'nplurals=2; plural=(n > 1);','language'=>'pt_BR','project-id-version'=>'Exchange Rate Pricing for WooCommerce 1.0.0','pot-creation-date'=>'2026-10-01T10:41:56+00:00','po-revision-date'=>'2026-10-01T10:41:56+00:00','messages'=>['Exchange Rate Pricing for WooCommerce'=>'Preços por Taxa de Câmbio para WooCommerce','Price products in a foreign currency such as USD and sell them in your store currency using an exchange rate you control, with markup, rounding and sale rules.'=>'Defina os preços dos produtos em uma moeda estrangeira, como o dólar (USD), e venda na moeda da sua loja usando uma taxa de câmbio que você controla, com margem, arredondamento e regras de promoção.','Reza Rajabi'=>'Reza Rajabi','Calculating…'=>'Calculando…','Could not calculate the price.'=>'Não foi possível calcular o preço.','Calculated from the exchange rate. Edit the base currency price instead.'=>'Calculado a partir da taxa de câmbio. Edite o preço na moeda base.','The exchange rate was saved. Prices are being recalculated in the background.'=>'A taxa de câmbio foi salva. Os preços estão sendo recalculados em segundo plano.','The exchange rate could not be saved. Enter a number greater than zero.'=>'Não foi possível salvar a taxa de câmbio. Digite um número maior que zero.','Update the rate'=>'Atualizar a taxa','Exchange Rate Pricing: no %s exchange rate is set yet, so exchange-rate priced products keep their current prices.'=>'Preços por Taxa de Câmbio: ainda não há uma taxa de câmbio para %s, então os produtos com preço por taxa de câmbio mantêm os preços atuais.','Exchange Rate Pricing: the %1$s rate was last updated %2$s ago.'=>'Preços por Taxa de Câmbio: a taxa de %1$s foi atualizada pela última vez há %2$s.','Recalculating prices… %1$s of %2$s products checked.'=>'Recalculando preços… %1$s de %2$s produtos verificados.','Last run %1$s ago. Checked: %2$s · Updated: %3$s · Missing a base price: %4$s'=>'Última execução há %1$s. Verificados: %2$s · Atualizados: %3$s · Sem preço base: %4$s','Waiting for an exchange rate.'=>'Aguardando uma taxa de câmbio.','Prices have not been recalculated yet.'=>'Os preços ainda não foram recalculados.','Exchange rate markup (%)'=>'Margem para preço por câmbio (%)','Exchange rate fixed markup (%s)'=>'Margem fixa para preço por câmbio (%s)','Leave empty to use the parent category or store markup.'=>'Deixe em branco para usar a margem da categoria mãe ou da loja.','Exchange rate (%s)'=>'Taxa de câmbio (%s)','Manual price'=>'Preço manual','Pricing'=>'Tipo de preço','Store default (%s)'=>'Padrão da loja (%s)','Exchange rate: the store price is calculated from a base currency price and updated automatically when the rate changes.'=>'Taxa de câmbio: o preço da loja é calculado a partir de um preço na moeda base e atualizado automaticamente quando a taxa muda.','Markup (%)'=>'Margem (%)','Leave empty to use the category or store markup (shown as placeholder).'=>'Deixe em branco para usar a margem da categoria ou da loja (mostrada no campo).','Fixed markup (%s)'=>'Margem fixa (%s)','Leave empty to use the category or store value (shown as placeholder).'=>'Deixe em branco para usar o valor da categoria ou da loja (mostrado no campo).','Base regular price (%s)'=>'Preço normal base (%s)','Base sale price (%s)'=>'Preço promocional base (%s)','Discount (%)'=>'Desconto (%)','Store price'=>'Preço na loja','Product not found.'=>'Produto não encontrado.','Set the exchange rate first.'=>'Defina a taxa de câmbio primeiro.','Enter a base regular price to calculate.'=>'Digite um preço normal base para calcular.','%1$s, on sale for %2$s'=>'%1$s, em promoção por %2$s','%1$s · markup %2$s%% + %3$s'=>'%1$s · margem %2$s%% + %3$s','Base price (%s)'=>'Preço base (%s)','Manual'=>'Manual','Missing base price'=>'Sem preço base','Store default'=>'Padrão da loja','Exchange rate pricing'=>'Preço por taxa de câmbio','— No change —'=>'— Sem alteração —','Saving…'=>'Salvando…','The exchange rate could not be saved.'=>'Não foi possível salvar a taxa de câmbio.','Exchange rate'=>'Taxa de câmbio','%s: no rate'=>'%s: sem taxa','No rate set yet.'=>'Nenhuma taxa definida ainda.','Updated %s ago.'=>'Atualizada há %s.','1 %s ='=>'1 %s =','Update'=>'Atualizar','Exchange rate settings'=>'Configurações da taxa de câmbio','Invalid currency.'=>'Moeda inválida.','The exchange rate must be a number greater than zero.'=>'A taxa de câmbio deve ser um número maior que zero.','You are not allowed to change the exchange rate.'=>'Você não tem permissão para alterar a taxa de câmbio.','Saved. Prices are being recalculated.'=>'Salvo. Os preços estão sendo recalculados.','The rate is unchanged; marked as up to date.'=>'A taxa não mudou; foi marcada como atualizada.','Exchange rates'=>'Taxas de câmbio','Products priced by exchange rate get their store price from a base currency price, this rate, your markup and rounding. Prices are saved as normal WooCommerce prices, so sorting, filters, carts and payment gateways work as usual.'=>'Produtos com preço por taxa de câmbio recebem o preço da loja a partir de um preço na moeda base, desta taxa, da sua margem e do arredondamento. Os preços são salvos como preços normais do WooCommerce, então ordenação, filtros, carrinhos e gateways de pagamento funcionam normalmente.','Base currency'=>'Moeda base','The currency you enter product prices in.'=>'A moeda em que você informa os preços dos produtos.','Enter amounts in'=>'Informar valores em','Toman'=>'Toman','Rial (store currency)'=>'Rial (moeda da loja)','Used for the rate, fixed markup and rounding step. Prices are always saved in Rial.'=>'Usado para a taxa, a margem fixa e o passo de arredondamento. Os preços são sempre salvos em Rial.','Rate source'=>'Origem da taxa','Where the exchange rate comes from. Extensions can add automatic sources.'=>'De onde vem a taxa de câmbio. Extensões podem adicionar origens automáticas.','Current rate'=>'Taxa atual','Outdated rate warning'=>'Aviso de taxa desatualizada','Warn in the admin when the rate is older than this many days. 0 turns the warning off.'=>'Avisar no painel quando a taxa tiver mais que este número de dias. 0 desativa o aviso.','Admin bar'=>'Barra de administração','Show the rate in the admin bar with a quick update form'=>'Mostrar a taxa na barra de administração com um formulário de atualização rápida','Products'=>'Produtos','Default pricing'=>'Tipo de preço padrão','Manual price: products opt in one by one'=>'Preço manual: ative a taxa de câmbio produto a produto','Exchange rate: all products are priced in %s'=>'Taxa de câmbio: todos os produtos têm preço em %s','Applies to products set to "Store default". Each product can override it.'=>'Aplica-se aos produtos definidos como "Padrão da loja". Cada produto pode substituir esta opção.','Sale prices'=>'Preços promocionais','Base currency sale price or discount percent'=>'Preço promocional na moeda base ou percentual de desconto','Base currency sale price only'=>'Apenas preço promocional na moeda base','Discount percent only'=>'Apenas percentual de desconto','When a product has both, the sale price wins.'=>'Quando um produto tem os dois, o preço promocional prevalece.','Markup'=>'Margem','Added on top of the converted price. Product categories and single products can override these values; leave their fields empty to inherit.'=>'Adicionada ao preço convertido. Categorias de produtos e produtos individuais podem substituir estes valores; deixe os campos deles em branco para herdar.','Markup percent'=>'Margem percentual','Fixed markup'=>'Margem fixa','Added after the percent markup.'=>'Adicionada depois da margem percentual.','Products in several categories'=>'Produtos em várias categorias','Use the highest category markup'=>'Usar a maior margem entre as categorias','Use the lowest category markup'=>'Usar a menor margem entre as categorias','Rounding'=>'Arredondamento','Round to multiples of'=>'Arredondar para múltiplos de','For example 10000 turns 48,372,500 into 48,380,000. 0 turns rounding off.'=>'Por exemplo, 10000 transforma 48.372.500 em 48.380.000. 0 desativa o arredondamento.','Rounding direction'=>'Direção do arredondamento','Up'=>'Para cima','Nearest'=>'Mais próximo','Down'=>'Para baixo','Recalculation'=>'Recálculo','Prices are recalculated automatically in the background whenever the rate, these settings or a category markup change.'=>'Os preços são recalculados automaticamente em segundo plano sempre que a taxa, estas configurações ou a margem de uma categoria mudam.','Status'=>'Status','Batch size'=>'Tamanho do lote','Products processed per background step. Lower it on slow hosting.'=>'Produtos processados por etapa em segundo plano. Diminua em hospedagens lentas.','Rate history'=>'Histórico de taxas','Uninstall'=>'Desinstalação','Remove data'=>'Remover dados','Delete settings, rate history and base prices when the plugin is deleted. Store prices and order records are kept.'=>'Excluir configurações, histórico de taxas e preços base quando o plugin for excluído. Os preços da loja e os registros de pedidos são mantidos.','Updated %1$s ago by %2$s.'=>'Atualizada há %1$s por %2$s.','No rate set yet. Prices are only calculated once a rate is saved.'=>'Nenhuma taxa definida ainda. Os preços só são calculados depois que uma taxa for salva.','Recalculate all prices now'=>'Recalcular todos os preços agora','No rate changes yet.'=>'Nenhuma alteração de taxa ainda.','Date'=>'Data','Rate'=>'Taxa','Change'=>'Variação','Source'=>'Origem','User'=>'Usuário','No rate set for %s.'=>'Nenhuma taxa definida para %s.','%1$s (updated %2$s ago)'=>'%1$s (atualizada há %2$s)','The rate must be a number.'=>'A taxa deve ser um número.','%1$s. %2$s'=>'%1$s. %2$s','Recalculation scheduled.'=>'Recálculo agendado.','Rate unchanged.'=>'Taxa sem alteração.','Scheduled recalculation of %d product.'=>'Recálculo de %d produto agendado.' . "\0" . 'Recálculo de %d produtos agendado.','Recalculating'=>'Recalculando','Recalculation: %1$s. %2$d of %3$d processed, %4$d updated, %5$d unchanged, %6$d missing a base price.'=>'Recálculo: %1$s. %2$d de %3$d processados, %4$d atualizados, %5$d sem alteração, %6$d sem preço base.','Exchange rate pricing mode'=>'Modo de preço por taxa de câmbio','Base regular price'=>'Preço normal base','Base sale price'=>'Preço promocional base','Base sale percent'=>'Percentual de desconto base','amount with unit%1$s %2$s'=>'%1$s %2$s','1 %1$s = %2$s'=>'1 %1$s = %2$s','Exchange rate at purchase'=>'Taxa de câmbio na compra','Base price: %s'=>'Preço base: %s','Settings'=>'Configurações','Exchange Rate Pricing for WooCommerce needs WooCommerce to be installed and active.'=>'O plugin Preços por Taxa de Câmbio para WooCommerce precisa que o WooCommerce esteja instalado e ativo.','Manual entry'=>'Entrada manual','Manual rates are entered by hand.'=>'Taxas manuais são digitadas à mão.']];